def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))

    if not alive:
        return max(0.0, min(budget, 18.0))

    serious = []
    for agent_id, opp in alive:
        if opp.get('budget', 0) > 0 and opp.get('hp', 0) > 0:
            serious.append((agent_id, opp))

    if not serious:
        return max(0.0, min(budget, 12.0))

    highest_prev = 0.0
    eric_prev = None
    rich_threat = 0.0
    for agent_id, opp in serious:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            if bid > highest_prev:
                highest_prev = bid
            if agent_id == 'Eric':
                eric_prev = bid
        if opp.get('budget', 0) > rich_threat:
            rich_threat = opp.get('budget', 0)

    slots = int(supply // WATER_REQ)
    if slots < 0:
        slots = 0

    serious_count = len(serious)
    contested = slots < (serious_count + 1)
    base_ref = highest_prev
    if eric_prev is not None:
        base_ref = max(base_ref, eric_prev)

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water >= 2:
        urgency += 3
    elif no_water >= 1:
        urgency += 1

    if contested:
        urgency += 2
    if slots <= 1:
        urgency += 1

    if budget < DAILY_SALARY * 0.8:
        urgency -= 1

    if urgency <= 1:
        bid = 16.0 if slots >= 2 else 28.0
        if base_ref > 0:
            bid = max(bid, min(base_ref * 0.22, 32.0))
    elif urgency == 2:
        bid = 34.0
        if base_ref > 0:
            bid = max(bid, min(base_ref * 0.38, 58.0))
    elif urgency == 3:
        bid = 58.0
        if base_ref > 0:
            bid = max(bid, min(base_ref * 0.55, 88.0))
    elif urgency == 4:
        bid = 82.0
        if base_ref > 0:
            bid = max(bid, min(base_ref * 0.72 + 2.0, 118.0))
    else:
        target = 96.0
        if base_ref > 0:
            target = max(target, min(base_ref + 3.0, 145.0))
        bid = target

    if eric_prev is not None and contested and urgency >= 4:
        bid = max(bid, min(eric_prev + 4.0, 150.0))

    if slots >= serious_count + 1 and urgency <= 3:
        bid = min(bid, 24.0)

    if day >= 8 and hp > 5 and no_water == 0 and contested:
        bid = min(bid, 52.0)

    if hp <= 1 or no_water >= 2:
        bid = max(bid, 105.0)

    if budget <= 0:
        return 0.0

    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = day_context['day']

    # Identify alive opponents and use only their previous_trace
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            prev = opp.get('previous_trace', {})
            if prev:
                alive_opps.append((opp_id, prev))

    if not alive_opps:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Extract yesterday bids to infer aggression level
    yesterday_bids = []
    for _, prev in alive_opps:
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 0.0

    # Supply pressure: higher supply usually reduces needed bid to secure water.
    # We'll map supply to a target bid fraction.
    # Use explicit int() for any indexing (none used), but keep calculations float-safe.
    supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY != MIN_SUPPLY else 0.5
    # More supply => lower target.
    base_frac = 0.62 - 0.25 * supply_norm

    # If opponents were bidding very high yesterday, increase slightly.
    if highest_prev_bid >= 0.85 * DAILY_SALARY:
        base_frac += 0.18
    elif avg_prev_bid >= 0.75 * DAILY_SALARY:
        base_frac += 0.08

    # My hp safety: if low hp, bid more aggressively.
    hp = float(my_status['hp'])
    no_water_days = int(my_status.get('no_water_days', 0))

    if hp <= 2 or no_water_days >= 2:
        base_frac = max(base_frac, 0.90)
    elif hp <= 4:
        base_frac = max(base_frac, 0.72)

    # Convert to bid, capped by budget.
    bid = DAILY_SALARY * base_frac

    # Ensure we don't spend too much when already safe.
    # If my hp is high and no-water-days is small, keep a tighter cap.
    if hp >= 7 and no_water_days <= 0:
        bid = min(bid, DAILY_SALARY * 0.70)

    bid = min(bid, float(my_status['budget']))

    # If budget is extremely low, still bid something minimal but nonzero.
    if bid <= 0:
        return 0.0
    return float(bid)
